    Object main,data,shop,market,ledger,vault,reset,monsters,mining,swords,transfers,armor,homes,newbies,trees,graves,events,serums,executioner,voice;Path report=Path.of("update25-checks.txt"),stateFile=Path.of("probe-state.properties");Properties state=new Properties();
    @Override public void onEnable(){main=Bukkit.getPluginManager().getPlugin("BlackWikiSMP");getCommand("probe").setExecutor(this);}
    Object get(Object o,String name)throws Exception{for(Class<?> c=o.getClass();c!=null;c=c.getSuperclass())try{Field f=c.getDeclaredField(name);f.setAccessible(true);return f.get(o);}catch(NoSuchFieldException ignored){}throw new NoSuchFieldException(name);}
    void set(Object o,String name,Object value)throws Exception{Field f=o.getClass().getDeclaredField(name);f.setAccessible(true);f.set(o,value);}
    Class<?> boxed(Class<?> c){return c==int.class?Integer.class:c==long.class?Long.class:c==boolean.class?Boolean.class:c;}
    Object call(Object target,String name,Object...args)throws Exception{Class<?> type=target instanceof Class<?> c?c:target.getClass();for(Class<?> c=type;c!=null;c=c.getSuperclass())for(Method m:c.getDeclaredMethods())if(m.getName().equals(name)&&m.getParameterCount()==args.length){boolean matches=true;for(int i=0;i<args.length;i++)if(args[i]!=null&&!boxed(m.getParameterTypes()[i]).isInstance(args[i]))matches=false;if(matches){m.setAccessible(true);try{return m.invoke(target instanceof Class?null:target,args);}catch(InvocationTargetException ex){throw new RuntimeException(name,ex.getCause());}}}throw new NoSuchMethodException(type+" "+name);}
    void check(boolean yes,String text)throws Exception{Files.writeString(report,(yes?"PASS ":"FAIL ")+text+"\n",StandardOpenOption.CREATE,StandardOpenOption.APPEND);if(!yes)throw new AssertionError(text);}
    Player player(String name){return Objects.requireNonNull(Bukkit.getPlayerExact(name),name+" is offline");}
    Object user(Player a)throws Exception{return call(data,"user",a);}
    long money(Player a)throws Exception{return (long)get(user(a),"coins");}
    void money(Player a,long value)throws Exception{set(user(a),"coins",value);call(vault,"saveAccount",a);}
    void save(Player a)throws Exception{call(vault,"saveAccount",a);}
    void click(Player a,int slot)throws Exception{Object holder=a.getOpenInventory().getTopInventory().getHolder();@SuppressWarnings("unchecked") Map<Integer,Consumer<Player>> actions=(Map<Integer,Consumer<Player>>)get(holder,"actions");Objects.requireNonNull(actions.get(slot),"No action "+slot).accept(a);}
    Object product(String id)throws Exception{return call(Class.forName("kr.blackwiki.smp.ShopCatalogue"),"find",id);}
    boolean shop(Player a,String id,boolean sell,int quantity)throws Exception{return (boolean)call(shop,"transact",a,product(id),sell,quantity);}
    int count(Player a,Material type){int count=0;for(ItemStack item:a.getInventory().getStorageContents())if(item!=null&&item.getType()==type)count+=item.getAmount();return count;}
    void fill(Player a){ItemStack[] items=new ItemStack[36];for(int i=0;i<36;i++)items[i]=new ItemStack(Material.COBBLESTONE,64);a.getInventory().setStorageContents(items);}
    @SuppressWarnings("unchecked") Collection<Object> entries()throws Exception{return (Collection<Object>)call(ledger,"all");}
    Object latest(Player a)throws Exception{return entries().stream().filter(l->{try{return call(l,"seller").equals(a.getUniqueId())&&call(l,"state").toString().equals("ACTIVE");}catch(Exception ex){throw new RuntimeException(ex);}}).reduce((x,y)->y).orElseThrow();}
    UUID id(Object l)throws Exception{return (UUID)call(l,"id");}
    String status(Object l)throws Exception{return call(l,"state").toString();}
    Object listing(UUID id)throws Exception{return call(ledger,"get",id);}
    void register(Player a,long price)throws Exception{call(market,"sellGui",a,price);click(a,40);}
    ItemStack special(Material material,int amount){ItemStack it=new ItemStack(material,amount);var meta=it.getItemMeta();meta.displayName(Component.text("판매 테스트 보물"));meta.lore(List.of(Component.text("원본 설명")));meta.getPersistentDataContainer().set(new NamespacedKey("probe","secret"),PersistentDataType.STRING,"preserve-me");if(meta instanceof org.bukkit.inventory.meta.Damageable d)d.setDamage(7);it.setItemMeta(meta);return it;}
    void receipt(Player a,String kind,UUID id)throws Exception{NamespacedKey key=new NamespacedKey((JavaPlugin)main,"market-receipts");String old=a.getPersistentDataContainer().getOrDefault(key,PersistentDataType.STRING,"");a.getPersistentDataContainer().set(key,PersistentDataType.STRING,old.isEmpty()?kind+"/"+id:old+"\n"+kind+"/"+id);save(a);}
    @SuppressWarnings({"unchecked","rawtypes"}) Object force(Object old,String newState,UUID buyer)throws Exception{Class<?> st=Class.forName("kr.blackwiki.smp.MarketLedger$State");var ctor=old.getClass().getDeclaredConstructors()[0];ctor.setAccessible(true);Object l=ctor.newInstance(call(old,"id"),call(old,"seller"),buyer,call(old,"price"),call(old,"item"),Enum.valueOf((Class)st,newState),call(old,"created"));call(ledger,"put",l);return l;}
    void stateSave()throws Exception{try(var out=Files.newOutputStream(stateFile)){state.store(out,"Runtime probe state");}}
    void mark(String text)throws Exception{Files.writeString(Path.of(text),"ok");getLogger().info(text);}
    Player a,b,c,n;Object design,upgrades;int tries;Location original;
    interface Checked{void run()throws Exception;}
    void later(long ticks,Checked run){Bukkit.getScheduler().runTaskLater(this,()->{try{run.run();}catch(Throwable ex){failure(ex);}},ticks);}
    void failure(Throwable ex){ex.printStackTrace();try{Files.writeString(Path.of("FAILED"),ex.toString());Files.writeString(report,"FAIL EXCEPTION "+ex+"\n",StandardOpenOption.CREATE,StandardOpenOption.APPEND);}catch(Exception ignored){}}
    @Override public boolean onCommand(CommandSender sender,Command cmd,String label,String[] args){try{data=get(main,"data");vault=get(main,"vaults");design=get(main,"spawnDesign");upgrades=get(main,"upgrades");a=player("Alice");b=player("Bob");c=player("Charlie");n=player("Newbie");if(Files.exists(stateFile))try(var in=Files.newInputStream(stateFile)){state.load(in);}switch(args[0]){case "phase1"->later(1,this::phase1);case "phase2"->later(1,this::phase2);case "phase3"->later(1,this::phase3);}}catch(Throwable ex){failure(ex);}return true;}
    void clearCombat()throws Exception{((Map<?,?>)get(get(main,"travel"),"combat")).clear();}
    void phase1()throws Exception{
        var cfg=((JavaPlugin)main).getConfig();check(((JavaPlugin)main).getDescription().getVersion().equals("2.5"),"2.5 enables on actual Paper 26.2 and Java 25");check(cfg.getInt("config-version")==25&&cfg.getString("discord.mode").equals("bot"),"2.4 config automatically migrates to schema twenty-five and bot mode");check(cfg.getInt("queue.player-slots")==5&&cfg.getInt("queue.max-waiting")==3,"existing game and queue capacities remain unchanged");check(!cfg.contains("discord.webhook-url")&&cfg.contains("discord.bot-token")&&cfg.contains("discord.channel-id"),"old webhook is retired and new bot fields are added automatically");Path backup=Path.of("plugins/BlackWikiSMP/config.yml.before-2.5.bak");check(Files.readString(backup).contains("old-test-only-token"),"migration preserves exact previous configuration in backup");state.setProperty("config-backup",java.util.HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(Files.readAllBytes(backup))));
        check((int)get(user(a),"vaultTier")==1&&((List<?>)get(user(a),"vault")).stream().anyMatch(x->!x.toString().isEmpty()),"2.4 native vault tier and original stored items survive upgrade");check(((Map<?,?>)get(user(a),"homes")).size()==5,"all five 2.4 homes survive upgrade");check((int)call(get(main,"armor"),"serumUses",a)==3&&a.getAttribute(Attribute.MAX_HEALTH).getValue()==26,"permanent serum health survives upgrade");check((boolean)call(get(main,"voice"),"ready"),"existing voice API integration remains enabled");
        original=(Location)call(main,"spawn");state.setProperty("old-y",Integer.toString(original.getBlockY()));Block block=original.getWorld().getBlockAt(original.getBlockX()+20,original.getBlockY(),original.getBlockZ()+20);block.setType(Material.CHEST,false);org.bukkit.block.Chest chest=(org.bukkit.block.Chest)block.getState();chest.getSnapshotInventory().setItem(0,special(Material.DIAMOND,9));chest.update(true,false);check(((org.bukkit.block.Chest)block.getState()).getBlockInventory().getItem(0).equals(special(Material.DIAMOND,9)),"existing chest fixture contains its original named items before build");state.setProperty("old-x",Integer.toString(block.getX()));state.setProperty("old-z",Integer.toString(block.getZ()));
        clearCombat();a.setOp(false);Bukkit.dispatchCommand(a,"스폰꾸미기 생성");check(!(boolean)call(design,"busy"),"non-OP cannot generate or alter spawn garden");a.setOp(true);Bukkit.dispatchCommand(a,"스폰꾸미기 생성");a.setOp(false);check((boolean)call(design,"busy"),"OP spawn command starts asynchronous chunk preparation");call(get(main,"backups"),"start",Bukkit.getConsoleSender());check(!(boolean)call(get(main,"backups"),"running"),"backup cannot race an unfinished spawn build");later(20,this::pauseBuild);
    }
    void pauseBuild()throws Exception{if(!get(design,"stage").equals("BUILDING")||(int)get(design,"index")<1000){if(++tries>100)throw new AssertionError("build did not start");later(10,this::pauseBuild);return;}check(!(boolean)call(design,"done")&&(boolean)call(design,"busy"),"real partially generated spawn is checkpointed before shutdown");check((int)get(design,"y")>Integer.parseInt(state.getProperty("old-y"))+8,"garden is placed in empty sky above original terrain");state.setProperty("floor",get(design,"y").toString());state.setProperty("center-x",get(design,"x").toString());state.setProperty("center-z",get(design,"z").toString());stateSave();clearCombat();mark("PHASE1_STOP_READY");}
    void phase2()throws Exception{later(20,this::completed);}
    void completed()throws Exception{if(!(boolean)call(design,"done")){if(++tries>120)throw new AssertionError("interrupted garden did not resume: "+call(design,"status"));later(20,this::completed);return;}
        check(true,"incomplete build automatically resumes after restart without clearing files");World world=(World)get(main,"spawnWorld");int x=Integer.parseInt(state.getProperty("center-x")),z=Integer.parseInt(state.getProperty("center-z")),y=Integer.parseInt(state.getProperty("floor"));Block old=world.getBlockAt(Integer.parseInt(state.getProperty("old-x")),Integer.parseInt(state.getProperty("old-y")),Integer.parseInt(state.getProperty("old-z")));check(old.getType()==Material.CHEST,"existing ground-level chest survives garden generation");check(((org.bukkit.block.Chest)old.getState()).getBlockInventory().getItem(0).equals(special(Material.DIAMOND,9)),"existing chest items retain full original metadata");
        List<?> plan=(List<?>)call(Class.forName("kr.blackwiki.smp.SpawnPlan"),"build");int wrong=0;boolean leaves=true;List<Map<String,Object>> preview=new ArrayList<>();for(Object v:plan){int dx=(int)call(v,"x"),dy=(int)call(v,"y"),dz=(int)call(v,"z");Material type=(Material)call(v,"type");Block actual=world.getBlockAt(x+dx,y+dy,z+dz);if(actual.getType()!=type)wrong++;preview.add(Map.of("x",dx,"y",dy,"z",dz,"material",type.name()));if(type.name().endsWith("_LEAVES"))leaves&=((org.bukkit.block.data.type.Leaves)actual.getBlockData()).isPersistent();}check(wrong==0,"all generated garden blocks match the deterministic design");check(leaves,"all generated garden leaves remain persistent");Files.writeString(Path.of("spawn-plan.json"),new com.google.gson.Gson().toJson(preview));check(world.getBlockAt(x-50,y,z).getType()!=Material.AIR&&world.getBlockAt(x+49,y,z).getType()!=Material.AIR&&world.getBlockAt(x-51,y,z).getType()==Material.AIR&&world.getBlockAt(x+50,y,z).getType()==Material.AIR,"decorated footprint is exactly one hundred blocks wide");Location spawn=(Location)call(main,"spawn");check(spawn.getBlockY()==y+1&&spawn.getBlockX()==x&&spawn.getBlockZ()==z+12,"safe spawn destination moves onto completed plaza");
        Object npcs=get(main,"npcs");Map<?,?> specs=(Map<?,?>)get(npcs,"specs");Object spec=specs.get("spawn-menu");check(spec!=null&&call(spec,"role").equals("메뉴"),"central menu NPC is durably registered");Entity npc=world.getNearbyEntities(new Location(world,x+.5,y+1,z+.5),2,3,2).stream().filter(e->e.getPersistentDataContainer().getOrDefault(new NamespacedKey((JavaPlugin)main,"guide"),PersistentDataType.STRING,"").equals("spawn-menu")).findFirst().orElseThrow();clearCombat();if(a.isDead())a.spigot().respawn();a.teleport(new Location(world,x+.5,y+1,z+2.5));Bukkit.getPluginManager().callEvent(new PlayerInteractEntityEvent(a,npc,EquipmentSlot.HAND));check(a.getOpenInventory().getTopInventory().getItem(11).getType()==Material.COMPASS,"central menu NPC right click opens main GUI");a.setOp(true);Bukkit.dispatchCommand(a,"스폰꾸미기");check(a.getOpenInventory().getTopInventory().getItem(13).getType()==Material.CHERRY_SAPLING,"spawn design command opens OP status GUI");Bukkit.dispatchCommand(a,"업데이트상태");Bukkit.dispatchCommand(a,"명령어");check(a.getOpenInventory().title().toString().contains("플레이어 명령어"),"existing Korean command guide remains routed correctly");
        var cfg=((JavaPlugin)main).getConfig();String invalid="invalid://private-test-value";cfg.set("discord.enabled",true);cfg.set("discord.bot-token",invalid);cfg.set("discord.channel-id","123456789");call(get(main,"discord"),"reload");String status=(String)call(get(main,"discord"),"status");check(status.contains("토큰")&&!status.contains(invalid),"invalid bot token is reported without exposing entered value");check(!(boolean)call(get(get(main,"discord"),"relay"),"offer","must not send"),"invalid bot settings cannot start outgoing HTTP requests");cfg.set("discord.enabled",false);cfg.set("discord.bot-token","");cfg.set("discord.channel-id","");call(get(main,"discord"),"reload");Bukkit.dispatchCommand(a,"디스코드");check(a.getOpenInventory().title().toString().contains("봇"),"Discord GUI displays bot-based setup");Bukkit.dispatchCommand(a,"smp slots 17");Bukkit.dispatchCommand(a,"smp waiting 11");cfg.set("spawn-design.auto-create",true);((JavaPlugin)main).saveConfig();a.setOp(false);
        world.getBlockAt(x+43,y,z+43).setType(Material.GOLD_BLOCK,false);world.save(true);for(Player user:List.of(a,b,c,n))save(user);stateSave();clearCombat();mark("PHASE2_STOP_READY");
    }
    void phase3()throws Exception{
        World world=(World)get(main,"spawnWorld");int x=Integer.parseInt(state.getProperty("center-x")),z=Integer.parseInt(state.getProperty("center-z")),y=Integer.parseInt(state.getProperty("floor"));check((boolean)call(design,"done")&&!(boolean)call(design,"busy"),"completed spawn does not regenerate on future restart");check(world.getBlockAt(x+43,y,z+43).getType()==Material.GOLD_BLOCK,"operator garden edits are retained after restart");var cfg=((JavaPlugin)main).getConfig();check(cfg.getInt("queue.player-slots")==17&&cfg.getInt("queue.max-waiting")==11,"automatic updates retain later operator configuration changes");String hash=java.util.HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(Files.readAllBytes(Path.of("plugins/BlackWikiSMP/config.yml.before-2.5.bak"))));check(hash.equals(state.getProperty("config-backup")),"original migration backup remains unchanged on repeated boots");check(((Map<?,?>)get(user(a),"homes")).size()==5&&(int)get(user(a),"vaultTier")==1&&(int)call(get(main,"armor"),"serumUses",a)==3,"homes vault upgrade and permanent buffs survive the complete upgrade cycle");world.getChunkAt(x>>4,z>>4);long count=world.getNearbyEntities(new Location(world,x+.5,y+1,z+.5),3,3,3).stream().filter(e->e.getPersistentDataContainer().getOrDefault(new NamespacedKey((JavaPlugin)main,"guide"),PersistentDataType.STRING,"").equals("spawn-menu")).count();check(count==1,"menu NPC is restored once without duplication");a.setOp(true);Bukkit.dispatchCommand(a,"플러그인상태");check(a.getOpenInventory().getTopInventory().getItem(33)!=null,"expanded plugin status GUI includes upgrade and spawn state");a.setOp(false);call(get(main,"backups"),"start",Bukkit.getConsoleSender());later(40,this::backupDone);
    }
    void backupDone()throws Exception{if((boolean)call(get(main,"backups"),"running")){later(20,this::backupDone);return;}Path folder=Path.of("backups/BlackWikiSMP");Path last;try(var files=Files.list(folder)){last=files.filter(p->p.toString().endsWith(".zip")).max(Comparator.naturalOrder()).orElseThrow();}try(var zip=new java.util.zip.ZipFile(last.toFile())){check(zip.getEntry("plugins/BlackWikiSMP/spawn-build.yml")!=null&&zip.getEntry("plugins/BlackWikiSMP/upgrade.yml")!=null,"backup includes spawn and automatic-upgrade journals");check(zip.getEntry("plugins/BlackWikiSMP/graves.yml")!=null&&zip.getEntry("plugins/BlackWikiSMP/event.yml")!=null,"existing grave and event backup records remain included");}clearCombat();mark("ALL_CHECKS_PASSED");}
